B.avg=s(["An egg is hidden in today\u2019s lesson!","Go on a word hunt!"],t.s)
B.aIg=s(["\u0152uf trouv\xe9, le\xe7on faite !","Joyeuses P\xe2ques, bravo !"],t.s)
B.aFa=s(["Egg found, lesson done!","Happy Easter, well done!"],t.s)
B.bow=new A.kr(B.aGS,B.avg,B.aIg,B.aFa,"Joyeuses P\xe2ques","Happy Easter")
